import{_ as t,H as i,f as l,i as r}from"./chunks/framework.BH2BK_3i.js";const C=JSON.parse('{"title":"特别放送｜好消息：我的C++新书即将出版","description":"","frontmatter":{},"headers":[],"relativePath":"现代C++编程实战/特别放送｜好消息：我的C++新书即将出版.md","filePath":"现代C++编程实战/特别放送｜好消息：我的C++新书即将出版.md","lastUpdated":1779821299000}'),o={name:"现代C++编程实战/特别放送｜好消息：我的C++新书即将出版.md"};function a(p,e,_,n,c,s){return i(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="特别放送-好消息-我的c-新书即将出版" tabindex="-1">特别放送｜好消息：我的C++新书即将出版 <a class="header-anchor" href="#特别放送-好消息-我的c-新书即将出版" aria-label="Permalink to &quot;特别放送｜好消息：我的C++新书即将出版&quot;">​</a></h1><p>你好，我是吴咏炜。</p><p>时光飞逝，从我的 C++ 专栏最早上线到现在，居然已经超过五年了。在这个专栏里，我分享了我的很多经验，也从你的问题里学到了很多。今天，我有一个特别的好消息，也想要跟你分享。</p><p>我在 2024 年的主要产出是一本 C++ 的技术书——《C++ 实战：核心技术与最佳实践》。书中有部分内容出自我的 C++ 专栏，两者之间有部分重叠，但这本书绝不是简单地把专栏内容集结成书。</p><p>有些之前讲过的部分（如模板、容器和迭代器）有很多更新甚至重写，融入了我在过去几年里的心得；而有些部分（如算法、chrono 库和契约式设计）则是全新的内容。</p><p>选材和组织方式也有很大的不同：专栏基本上一次写一个主题，且字数不能太少或太多；而写书则篇幅上更为自由，重点放在较为完整地讲述现代 C++ 里的核心技术和最佳实践上，同时也放弃了很多对标准 C++ 以外的知识的讲解（特别是开源库方面）。</p><p><strong>本书的主要内容包括：</strong></p><ul><li>C 和 C++ 的预备知识</li><li>对象生存期和 RAII</li><li>移动语义</li><li>模板和自动类型推导</li><li>字符串</li><li>标准模板库（STL），包括函数对象（含 lambda）、容器、迭代器和算法</li><li>视图（ <code>string_view</code>、 <code>span</code> 和 C++20 里的视图）</li><li>智能指针</li><li>现代 C++ 的其他一些重要改进</li><li>不同的错误处理方式（契约、异常、 <code>error_code</code>、 <code>expected</code> 等）</li><li>不同的对象传递方式</li><li>并发编程</li><li>异步编程</li><li>C++ 程序员应当掌握的一些基础工具</li></ul><p>总的来说，专栏适合于一次学习一个知识点，而书则适合系统学习以及后续的查阅参考。值得一提的是，为了方便查阅参考，我和图灵图书的老师还特意在本书里制作了索引，这在国内的技术书籍里应该是极其罕见的。</p><p>我相信，这本书的内容跟目前的专栏内容形成了很好的互补，可以帮助你夯实基础，并提供更多的 C++ 最佳实践和惯用法。</p><p>正如我在专栏的结束语里写到的，C++ 是一门古老但历久弥新的语言。虽然它有着很多的困难，但它也有着强大的生命力——从 TIOBE 编程语言排行榜上超过 C、目前占据第二的位置，就是一个证明。</p><p><strong>我也想要感谢你，C++ 的开发者和学习者，给予了 C++ 语言更多的活力，同时也给了我问题、反馈和动力，让我得以写下这本书。谢谢！</strong></p><p>这本书已经上架，目前处于预售阶段，你可以通过以下链接获得特惠价格的签名版： <a href="https://item.jd.com/14343227.html" target="_blank" rel="noreferrer">https://item.jd.com/14343227.html</a></p><p>不过这个价格不是公开价格，有效期也只到月末为止。在此之后，你可以搜索书名在京东或其他网站上购买该书，也可以通过以下链接访问书的信息（含代码示例和样章的下载）： <a href="https://www.ituring.com.cn/book/3410" target="_blank" rel="noreferrer">https://www.ituring.com.cn/book/3410</a></p><p>最后，再次祝你学习顺利，成为 C++ 高手！</p>',15)])])}const m=t(o,[["render",a]]);export{C as __pageData,m as default};
